// Checks hello.html matches its brief: the heading, one line under it, no external files.
// Run: node tools/scarlett-scenario/check-hello.mjs
import { readFileSync } from "node:fs";

const html = readFileSync(new URL("../../hello.html", import.meta.url), "utf8");
const fails = [];
const count = (re) => (html.match(re) || []).length;

if (!/<h1>\s*Hello from AI Studio\s*<\/h1>/.test(html)) fails.push('missing <h1>Hello from AI Studio</h1>');
if (count(/<h1[\s>]/g) !== 1) fails.push("expected exactly one <h1>");
if (count(/<p[\s>]/g) !== 1) fails.push("expected exactly one <p> line under the heading");
if (/<p>\s*<\/p>/.test(html)) fails.push("the line under the heading is empty");
if (/<(script|link)[\s>]|\bsrc=|@import/i.test(html)) fails.push("page must not load scripts, stylesheets or other files");
if (!/<meta charset="utf-8">/i.test(html)) fails.push("missing utf-8 charset (needed for the em dash)");

if (fails.length) {
  console.error("FAIL hello.html:\n- " + fails.join("\n- "));
  process.exit(1);
}
console.log("PASS hello.html: heading, one line, no external files");

